findings.rationale:
fmt.Sprintf inserts name directly into SQL. A caller can use quotes or SQL syntax to change the WHERE clause. Remove fmt and pass name as a query argument.

Proposed fix

import ( "database/sql" -	"fmt" )

// SearchUsers finds users by name. func (s *Store) SearchUsers(name string) (*sql.Rows, error) { -	query := fmt.Sprintf("SELECT id, email FROM users WHERE name = '%s'", name) -	return s.db.Query(query) +	return s.db.Query("SELECT id, email FROM users WHERE name = ?", name) }
